WITH parsed AS (SELECT id, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT CASE WHEN lowest_price >= 27 THEN 'PREMIUM' ELSE 'STANDARD' END AS lowest_price_tier, APPROX_PERCENTILE(lowest_price, 0.5) AS lowest_price_p50, ROUND(AVG(lowest_price), 2) AS avg_lowest_price, COUNT(DISTINCT id) AS distinct_ids FROM parsed GROUP BY CASE WHEN lowest_price >= 27 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING ROUND(AVG(lowest_price), 2) > 0 ORDER BY lowest_price_tier DESC
